mapper.select:
SELECT su.ID, su.ACCOUNT, su.PASSWORD, su.NICK_NAME, su.FROZEN, su.PERM_VER, 0 AS TENANT_ID
FROM SYS_ACCOUNT su
WHERE COALESCE(su.DELETED, 0) = 0
  AND (su.ACCOUNT = #{account,jdbcType=VARCHAR}
    OR su.TEL = #{account,jdbcType=VARCHAR}
    OR su.EMAIL = #{account,jdbcType=VARCHAR})

SELECT su.*
FROM SYS_ACCOUNT su
WHERE COALESCE(su.DELETED, 0) = 0
  AND (su.ACCOUNT = #{account,jdbcType=VARCHAR}
    OR su.TEL = #{account,jdbcType=VARCHAR}
    OR su.EMAIL = #{account,jdbcType=VARCHAR})
